-- Uploaded images: profile photos, profile covers and listing photos, each a row served by its id. profile_photos never
-- had an endpoint, so it is empty and goes.
ALTER TABLE "profile_photos" DROP CONSTRAINT "profile_photos_profile_id_fkey";
DROP TABLE "profile_photos";

CREATE TABLE "images" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "owner_id" UUID NOT NULL,
    "content" BYTEA NOT NULL,
    "content_type" TEXT NOT NULL,
    "width" INTEGER NOT NULL,
    "height" INTEGER NOT NULL,
    "crop_left" INTEGER,
    "crop_top" INTEGER,
    "crop_width" INTEGER,
    "crop_height" INTEGER,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "images_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "images_size_check" CHECK ("width" > 0 AND "height" > 0),
    -- A cover keeps the whole picture and the area the user picked; other images are stored cropped.
    CONSTRAINT "images_crop_check" CHECK (
        ("crop_left" IS NULL AND "crop_top" IS NULL AND "crop_width" IS NULL AND "crop_height" IS NULL)
        OR (
            "crop_left" >= 0 AND "crop_top" >= 0 AND "crop_width" > 0 AND "crop_height" > 0
            AND "crop_left" + "crop_width" <= "width" AND "crop_top" + "crop_height" <= "height"
        )
    )
);

CREATE INDEX "images_owner_id_idx" ON "images"("owner_id");

ALTER TABLE "images" ADD CONSTRAINT "images_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "accounts"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "profiles" ADD COLUMN "photo_id" UUID,
ADD COLUMN "cover_id" UUID;

CREATE UNIQUE INDEX "profiles_photo_id_key" ON "profiles"("photo_id");
CREATE UNIQUE INDEX "profiles_cover_id_key" ON "profiles"("cover_id");

ALTER TABLE "profiles" ADD CONSTRAINT "profiles_photo_id_fkey" FOREIGN KEY ("photo_id") REFERENCES "images"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_cover_id_fkey" FOREIGN KEY ("cover_id") REFERENCES "images"("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "listings" ADD COLUMN "photo_id" UUID;

CREATE UNIQUE INDEX "listings_photo_id_key" ON "listings"("photo_id");

ALTER TABLE "listings" ADD CONSTRAINT "listings_photo_id_fkey" FOREIGN KEY ("photo_id") REFERENCES "images"("id") ON DELETE SET NULL ON UPDATE CASCADE;
